// LuaTypeDefEmitter.cs
// Generates a LuaLS (sumneko) type definition file for IDE autocompletion.
//
// Output: meteor_api.lua
// Contains ---@class, ---@field, ---@param, ---@return, ---@enum annotations
// that LuaLS reads to provide autocomplete, hover docs, and type checking
// in editors like VSCode and JetBrains IDEs.
//
// Place the generated file in your scripts directory (or add its location
// to your .luarc.json workspace.library) and the LSP picks it up.

using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

namespace MeteorBindingGenerator;

public static class LuaTypeDefEmitter
{
    // C++ type -> LuaLS type string
    private static readonly Dictionary<string, string> TypeMap = new()
    {
        ["void"]           = "nil",
        ["int"]            = "integer",
        ["short"]          = "integer",
        ["long"]           = "integer",
        ["long long"]      = "integer",
        ["unsigned int"]   = "integer",
        ["unsigned char"]  = "integer",
        ["unsigned short"] = "integer",
        ["char"]           = "integer",
        ["float"]          = "number",
        ["double"]         = "number",
        ["bool"]           = "boolean",
        ["std::string"]    = "string",
        ["SString"]        = "string",
        ["size_t"]         = "integer",
        ["std::size_t"]    = "integer",
        ["uint32_t"]       = "integer",
        ["uint64_t"]       = "integer",
        ["int32_t"]        = "integer",
        ["int64_t"]        = "integer",
    };

    /// <summary>
    /// Generate the complete meteor_api.lua type definition file.
    /// </summary>
    public static void Emit(List<BoundClass> boundClasses, List<BoundEnum> boundEnums, string outputDir)
    {
        var sb = new StringBuilder();

        EmitHeader(sb);
        EmitMathTypes(sb);
        EmitEnums(sb, boundEnums);
        EmitClasses(sb, boundClasses);
        EmitSelfGlobal(sb);

        var filePath = Path.Combine(outputDir, "meteor_api.lua");
        File.WriteAllText(filePath, sb.ToString());
        Console.WriteLine($"  Generated: meteor_api.lua (LuaLS type definitions)");
    }

    // ---- Header -------------------------------------------------------------

    private static void EmitHeader(StringBuilder sb)
    {
        sb.AppendLine("---@meta");
        sb.AppendLine("-- meteor_api.lua");
        sb.AppendLine("-- AUTO-GENERATED by MeteorBindingGenerator. DO NOT EDIT.");
        sb.AppendLine("--");
        sb.AppendLine("-- LuaLS (sumneko) type definitions for the Meteor engine Lua API.");
        sb.AppendLine("-- Place this file in your scripts directory or add its path to");
        sb.AppendLine("-- .luarc.json \"workspace.library\" for IDE autocompletion.");
        sb.AppendLine();
    }

    // ---- Math types (manually bound, not generated) -------------------------

    private static void EmitMathTypes(StringBuilder sb)
    {
        sb.AppendLine("-- ============================================================");
        sb.AppendLine("-- Math Types (manually bound via math_bindings.h)");
        sb.AppendLine("-- ============================================================");
        sb.AppendLine();

        // Kept in MathTypesStub below - hand-written to match math_bindings.h.
        sb.Append(MathTypesStub);

        // Asset handle (manually bound in asset_bindings.h)
        sb.Append(AssetHandleStub);

        // MLogger (static utility, manually bound)
        sb.AppendLine("---@class MLogger");
        sb.AppendLine("MLogger = {}");
        sb.AppendLine();
        sb.AppendLine("---@param msg string");
        sb.AppendLine("function MLogger.info(msg) end");
        sb.AppendLine();
        sb.AppendLine("---@param msg string");
        sb.AppendLine("function MLogger.verbose(msg) end");
        sb.AppendLine();
        sb.AppendLine("---@param msg string");
        sb.AppendLine("function MLogger.warn(msg) end");
        sb.AppendLine();
        sb.AppendLine("---@param msg string");
        sb.AppendLine("function MLogger.error(msg) end");
        sb.AppendLine();

        // Behaviour (Lua-side base class for script types)
        sb.AppendLine("-- ---- Script System ----");
        sb.AppendLine();
        sb.AppendLine("---@class Behaviour");
        sb.AppendLine("---@overload fun(obj: any): Behaviour|nil");
        sb.AppendLine("Behaviour = {}");
        sb.AppendLine();
        sb.AppendLine("function Behaviour:onStart() end");
        sb.AppendLine("function Behaviour:onTick(dt) end");
        sb.AppendLine("function Behaviour:onFixedTick(dt) end");
        sb.AppendLine("function Behaviour:onLateTick(dt) end");
        sb.AppendLine("function Behaviour:onStop() end");
        sb.AppendLine();
        sb.AppendLine("--- Create a new class extending this one. Scripts declare classes with CLASS instead,");
        sb.AppendLine("--- which calls this and also makes the class importable.");
        sb.AppendLine("---@param t table|nil");
        sb.AppendLine("---@return table");
        sb.AppendLine("function Behaviour:extend(t) end");
        sb.AppendLine();

        // Script declaration functions. The engine gives each script its own
        // copy while the file loads; these stubs are for LuaLS only.
        sb.AppendLine("--- Sets the script's module (namespace). Optional, once, before CLASS.");
        sb.AppendLine("--- Without it the module is meteor.game. Use a string literal: MODULE \"game.camera\"");
        sb.AppendLine("---@param name string");
        sb.AppendLine("function MODULE(name) end");
        sb.AppendLine();
        sb.AppendLine("--- Declares the script's class: `local X = CLASS(\"X\", Behaviour) { ... }`.");
        sb.AppendLine("--- The full name `<module>.X` is what import() takes. Calling the class casts:");
        sb.AppendLine("--- `X(obj)` returns obj if it is an X (or a subclass), otherwise nil.");
        sb.AppendLine("---@generic T");
        sb.AppendLine("---@param name `T` the class name, as a string literal");
        sb.AppendLine("---@param base Behaviour|any Behaviour, or a class from import()");
        sb.AppendLine("---@return fun(members: table): T");
        sb.AppendLine("function CLASS(name, base) end");
        sb.AppendLine();

        // Script access methods (manually bound on MSpatialEntity)
        // import() and every script class are declared in script_index.lua,
        // which the editor generates per project.
        sb.AppendLine("--- Returns this entity's script instance. Cast it to its class to use it:");
        sb.AppendLine("--- `CameraController(entt:getScript())` returns nil if the script is something else.");
        // Deliberately `table`: LuaLS can't see members written inside the
        // Behaviour:extend { ... } table, so a narrower type would flag every
        // method call on an un-cast script as an undefined field.
        sb.AppendLine("---@return table|nil");
        sb.AppendLine("function MSpatialEntity:getScript() end");
        sb.AppendLine();

    }

    // ---- Enums --------------------------------------------------------------

    private static void EmitEnums(StringBuilder sb, List<BoundEnum> enums)
    {
        if (enums.Count == 0) return;

        sb.AppendLine("-- ============================================================");
        sb.AppendLine("-- Enums");
        sb.AppendLine("-- ============================================================");
        sb.AppendLine();

        foreach (var e in enums)
        {
            sb.AppendLine($"---@enum {e.Name}");
            sb.AppendLine($"{e.Name} = {{");
            for (int i = 0; i < e.Values.Count; i++)
            {
                var comma = (i < e.Values.Count - 1) ? "," : "";
                // The real value (e.g. EKeyCode.Unknown = -1 shifts every
                // later key). Falls back to the index when it is not a literal.
                long value = i < e.NumericValues.Count && e.NumericValues[i].HasValue
                    ? e.NumericValues[i]!.Value
                    : i;
                sb.AppendLine($"    {e.Values[i]} = {value}{comma}");
            }
            sb.AppendLine("}");
            sb.AppendLine();
        }
    }

    // ---- Classes ------------------------------------------------------------

    private static void EmitClasses(StringBuilder sb, List<BoundClass> classes)
    {
        if (classes.Count == 0) return;

        // Build set of bound class names for parent resolution
        var boundNames = new HashSet<string>(classes.Select(c => c.Name));

        sb.AppendLine("-- ============================================================");
        sb.AppendLine("-- Classes");
        sb.AppendLine("-- ============================================================");
        sb.AppendLine();

        foreach (var cls in classes)
        {
            // Class declaration with optional parent
            var boundParent = cls.ParentClasses.FirstOrDefault(p => boundNames.Contains(p));
            if (boundParent != null)
                sb.AppendLine($"---@class {cls.Name} : {boundParent}");
            else
                sb.AppendLine($"---@class {cls.Name}");

            // Properties as fields
            foreach (var prop in cls.Properties)
            {
                var luaType = MapType(prop.CppType);
                sb.AppendLine($"---@field {prop.Name} {luaType}");
            }

            sb.AppendLine($"{cls.Name} = {{}}");
            sb.AppendLine();

            // Methods
            foreach (var func in cls.Functions)
            {
                EmitFunction(sb, cls.Name, func);
            }
        }
    }

    // ---- Function emission --------------------------------------------------

    private static void EmitFunction(StringBuilder sb, string className, BoundFunction func)
    {
        // Parameter annotations. Template types (vectors, asset handles) are
        // read from the header text: the AST pass can drop template arguments.
        for (int i = 0; i < func.Parameters.Count; i++)
        {
            var (type, name) = func.Parameters[i];
            if (i < func.DeclaredParameters.Count && func.DeclaredParameters[i].Type.Contains('<'))
                type = func.DeclaredParameters[i].Type;
            sb.AppendLine($"---@param {name} {MapType(type)}");
        }

        // Return annotation (skip for void)
        if (func.ReturnType != "void")
        {
            var returnType = func.DeclaredReturnType.Contains('<') ? func.DeclaredReturnType : func.ReturnType;
            sb.AppendLine($"---@return {MapType(returnType)}");
        }

        // Function signature: static uses dot, instance uses colon
        var paramNames = string.Join(", ", func.Parameters.Select(p => p.Name));
        var separator = func.IsStatic ? "." : ":";
        sb.AppendLine($"function {className}{separator}{func.Name}({paramNames}) end");
        sb.AppendLine();
    }

    // ---- Self global --------------------------------------------------------

    private static void EmitSelfGlobal(StringBuilder sb)
    {
        sb.AppendLine("-- ============================================================");
        sb.AppendLine("-- Global 'self' reference");
        sb.AppendLine("-- ============================================================");
        sb.AppendLine("-- The engine injects 'self' into every script environment,");
        sb.AppendLine("-- pointing to the owning MSpatialEntity (or subclass).");
        sb.AppendLine("-- Type it as MSpatialEntity for base autocompletion.");
        sb.AppendLine("-- Scripts for specific entity types can override with:");
        sb.AppendLine("--   ---@type MCollisionBodyEntity");
        sb.AppendLine("--   local self = self");
        sb.AppendLine();
        sb.AppendLine("---@type MSpatialEntity");
        sb.AppendLine("self = nil");
    }

    // ---- Type mapping -------------------------------------------------------

    /// <summary>
    /// Map a C++ type string to a LuaLS type annotation.
    /// Known primitives map to number/boolean/string.
    /// Everything else passes through as a class name (stripping const/ref/ptr).
    /// </summary>
    private static string MapType(string cppType)
    {
        var compact = System.Text.RegularExpressions.Regex.Replace(
            cppType.Replace("const ", "").Replace("&", ""), @"\s*([<>*,])\s*", "$1").Trim();

        // C strings are pushed to Lua as strings, not as char.
        if (compact == "char*")
            return "string";

        // std::vector<T> crosses the boundary as an indexable container.
        if (compact.StartsWith("std::vector<") && compact.EndsWith(">"))
            return MapType(compact["std::vector<".Length..^1]) + "[]";

        // Asset handles and refs all cross as MAssetHandle (CodeEmitter converts).
        if (compact.StartsWith("TAssetHandle") || compact.StartsWith("TAssetRef"))
            return "MAssetHandle";

        // Any other template has no Lua-side binding and reaches scripts as
        // opaque userdata.
        if (compact.Contains('<'))
            return "userdata";

        // Strip const, &, * qualifiers for lookup
        var cleaned = cppType
            .Replace("const ", "")
            .Replace("&", "")
            .Replace("*", "")
            .Trim();

        if (TypeMap.TryGetValue(cleaned, out var luaType))
            return luaType;

        // If it's a known class/enum name, return as-is
        // Otherwise return as-is too (it might be a class the user hasn't bound yet)
        return cleaned;
    }
    // ---- Asset handle stub text --------------------------------------------
    // Keep in sync with asset_bindings.h.
    private const string AssetHandleStub = """
        --- Reference to an asset by GUID, looked up on every get(), so it stays
        --- valid across asset reloads. Get one from MAssetManager.find(path) or
        --- any function that returns an asset. Functions that take an asset
        --- accept it; a handle to the wrong asset type counts as null there.
        ---
        ---   local handle = MAssetManager.find("assets/ui/logo.png")
        ---   local texture = MTextureAsset(handle:get())   -- nil if not a texture
        ---@class MAssetHandle
        MAssetHandle = {}

        --- The asset now, or nil if the handle is null or the asset isn't
        --- loaded. Use it right away - fetch again instead of storing it.
        ---@return MAsset|nil
        function MAssetHandle:get() end

        --- True when the handle points at a loaded asset.
        ---@return boolean
        function MAssetHandle:isValid() end

        --- True when the handle was never assigned.
        ---@return boolean
        function MAssetHandle:isNull() end

        ---@return string
        function MAssetHandle:getAssetId() end

        --- The asset's path, or "" when it isn't loaded.
        ---@return string
        function MAssetHandle:getPath() end

        --- "guid:<id>", the form scene files store.
        ---@return string
        function MAssetHandle:toRefString() end

        --- Handle for an asset object you already have.
        ---@param asset MAsset
        ---@return MAssetHandle
        function MAssetHandle.fromAsset(asset) end

        --- A null handle - pass it to clear an asset slot.
        ---@return MAssetHandle
        function MAssetHandle.none() end

        """;

